import type { Dict } from '../index';

/**
 * Operator / creator pages (workstream operator-copy): sign-in, my knowledge (dashboard), manage, logs, register (new patch),
 * account settings, files & changes (aindrive). Plain language first; technical names stay in tooltips via tech().
 *
 * Local glossary-style terms defined here (not in glossary.ts, which is shared):
 *   op.term.integrity  — 무결성 검사 / integrity check (hash-only attestation: body sha256 + benchmark hash match, no model run)
 *   op.term.executed   — 실행 검증 / executed verification (verifier loaded the knowledge into a real model and scored it)
 *   op.term.gateway    — 자동 결제 주소 / automatic-payment address (x402 gateway URL an agent can pay at)
 */
